<?php
declare(strict_types=1);
/** Renderização privada, preservando HTML da versão 1.0.37. */
function bus_admin_view_import(PDO $db,string $action): void {
    if($action==='bus_import') {
        $page=max(1,min(10000,(int)($_GET['page']??1)));$limit=120;$offset=($page-1)*$limit;
        $totalPending=(int)$db->query("SELECT COUNT(*) FROM bus_import_queue WHERE status='pending'")->fetchColumn();
        $pending=$db->query("SELECT * FROM bus_import_queue WHERE status='pending' ORDER BY created_at DESC,id DESC LIMIT ".$limit." OFFSET ".$offset)->fetchAll();
        ?><section class="panel"><div class="panel-heading"><div><h2>Dados oficiais · DER-MG e ANTT</h2><p class="muted">Importe arquivos oficiais, confira cada trajeto e publique somente após revisão. Linhas fixas nunca serão sobrescritas.</p></div><a href="/admin.php?action=bus" class="btn outline small">← Linhas</a></div>
        <div class="alert warning">A publicação oficial não confirma que o ônibus esteja circulando hoje. Partidas intermediárias e chegadas sem hora oficial não serão estimadas.</div>
        <div class="bus-import-grid"><div class="bus-import-card"><h3>DER-MG · intermunicipal</h3><p>Baixe o arquivo <strong>Quadro de Horários Intermunicipal</strong> (texto) no portal do DER-MG. Selecione <strong>quadro_horario_inter.txt</strong>, não o arquivo de itinerários ou pontos de parada. Aceita cabeçalhos COD_LINH, NOME_LINH, HORA_PARTIDA, TRAJETO e dias, com separadores comuns. Sem horários de paradas intermediárias, a chegada não será estimada.</p><a href="<?=h(IGUA_DER_CATALOG)?>" target="_blank" rel="noopener noreferrer">Abrir catálogo oficial ↗</a></div><div class="bus-import-card"><h3>ANTT · interestadual</h3><p>Importe o CSV oficial de Horários SIGMA ou utilize o download automático do arquivo de setembro/2026. O catálogo publica novas edições periodicamente.</p><a href="<?=h(IGUA_ANTT_CATALOG)?>" target="_blank" rel="noopener noreferrer">Abrir catálogo oficial ↗</a></div></div>
        <form class="stacked-form" method="post" action="/admin.php?action=bus_stage_import" enctype="multipart/form-data"><?=csrf_field()?><div class="form-grid"><label>Fonte<select name="source"><option value="der_mg">DER-MG</option><option value="antt">ANTT</option></select></label><label>Filtro opcional de cidade<input name="city_filter" value="Iguatama" maxlength="100" placeholder="Iguatama"></label><label class="full">Arquivo oficial CSV/TXT (máximo 15 MB; limite PHP atual: <?=h(ini_get('upload_max_filesize'))?>)<input type="file" name="official_file" accept=".csv,.txt,text/csv,text/plain"></label></div><label class="checkbox-line"><input type="checkbox" name="remote_antt" value="1"> <span>Baixar automaticamente CSV da ANTT (setembro/2026), ignorando arquivo enviado</span></label><button class="btn primary">Verificar e preparar importação</button></form>
        <h3 style="margin-top:28px">Aguardando revisão (<?=$totalPending?> linhas)</h3>
        <?php if($pending):?><div class="table-wrap"><table><thead><tr><th>Fonte</th><th>Trajeto</th><th>Partidas</th><th>Ações</th></tr></thead><tbody><?php foreach($pending as $p):$info=json_decode($p['payload'],true);?><tr><td><?=h($p['source']==='antt'?'ANTT':'DER-MG')?></td><td><?=h($info['name']??'')?><small class="muted"> · <?=h($info['company']??'')?></small></td><td><?=count($info['departures']??[])?></td><td class="action-cell"><form method="post" action="/admin.php?action=bus_approve_import"><?=csrf_field()?><input type="hidden" name="id" value="<?=(int)$p['id']?>"><button data-confirm="Publicar esta linha com os horários do arquivo?">Aprovar</button></form><form method="post" action="/admin.php?action=bus_ignore_import"><?=csrf_field()?><input type="hidden" name="id" value="<?=(int)$p['id']?>"><button>Ignorar</button></form></td></tr><?php endforeach;?></tbody></table></div><?php else:?><p class="muted">Nenhuma linha nesta página. Envie um arquivo oficial ou volte à página anterior.</p><?php endif;?>
        <?php if($totalPending>$limit):?><nav class="admin-subnav" aria-label="Páginas de importação"><?php if($page>1):?><a href="/admin.php?action=bus_import&page=<?=$page-1?>">← Anteriores</a><?php endif;?><span>Página <?=$page?> de <?=ceil($totalPending/$limit)?></span><?php if($page*$limit<$totalPending):?><a href="/admin.php?action=bus_import&page=<?=$page+1?>">Próximas →</a><?php endif;?></nav><?php endif;?></section><?php return;
    }
}
